oxy_webhelp_navlinks = {"tocId-d39307e43567":{"topics":[{"title":"Atlassian Confluence protection requirements","shortdesc":"<p class=\"shortdesc\">Your Atlassian site and accounts must meet specific requirements before you add an         Atlassian Confluence site to <span class=\"ph\">RSC<\/span>.<\/p>","href":"confluence\/confluence_requirements.html","attributes":{"data-id":"confluence_requirements"},"menu":{"hasChildren":false},"tocID":"confluence_requirements-d39307e43568","topics":[]},{"title":"Supported Atlassian Confluence data types","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> backs up Atlassian Confluence spaces and restores pages, blog         posts, attachments, and related metadata, with some limitations.<\/p>","href":"confluence\/confluence_supported_data_types.html","attributes":{"data-id":"confluence_supported_data_types"},"menu":{"hasChildren":false},"tocID":"confluence_supported_data_types-d39307e43582","topics":[]},{"title":"OAuth authentication for Atlassian Confluence site connection","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> uses OAuth to connect to the Atlassian site that you want to         protect. You must use the global administrator credentials of the site to authorize the         connection.<\/p>","href":"confluence\/confluence_permissions.html","attributes":{"data-id":"confluence_permissions"},"menu":{"hasChildren":false},"tocID":"confluence_permissions-d39307e43595","topics":[]},{"title":"Required RBAC permissions for Atlassian Confluence","shortdesc":"<p class=\"shortdesc\">Managing Atlassian Confluence protection in <span class=\"ph\">RSC<\/span> requires a role with         the appropriate RBAC permissions.<\/p>","href":"confluence\/confluence_rbac.html","attributes":{"data-id":"confluence_rbac"},"menu":{"hasChildren":false},"tocID":"confluence_rbac-d39307e43608","next":"confluence_rbac-d39307e43608"}]}};